<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Game state
        let player = { x: 0, y: 0 };
        let tiles = {};
        let inventory = { seeds: 10, crops: 0 };
        let day = 0;

        // Game logic
        function update() {
            // Move player
            if (event.key === 'ArrowUp') player.y -= 1;
            if (event.key === 'ArrowDown') player.y += 1;
            if (event.key === 'ArrowLeft') player.x -= 1;
            if (event.key === 'ArrowRight') player.x += 1;

            // Plant seed
            if (event.key === 'p') {
                const seed = { crop: 'corn', stage: 0 };
                tiles[player.x + ',' + player.y] = seed;
                inventory.seeds--;
            }

            // Harvest crop
            if (event.key === 'h') {
                const tile = tiles[player.x + ',' + player.y];
                if (tile && tile.crop === 'corn' && tile.stage === 3) {
                    tiles[player.x + ',' + player.y] = null;
                    inventory.crops++;
                }
            }

            // Update time
            day++;
            for (const tile in tiles) {
                const seed = tiles[tile];
                if (seed) {
                    seed.stage++;
                    if (seed.stage === 3) {
                        delete tiles[tile];
                        inventory.crops++;
                    }
                }
            }

            // Draw tiles
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (const tile in tiles) {
                const seed = tiles[tile];
                if (seed) {
                    drawSeed(seed);
                }
            }

            // Save game
            if (event.key === 's') {
                localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
            }

            // Load game
            if (event.key === 'l') {
                const savedGame = localStorage.getItem('game');
                if (savedGame) {
                    const state = JSON.parse(savedGame);
                    player = state.player;
                    tiles = state.tiles;
                    inventory = state.inventory;
                    day = state.day;
                }
            }

            requestAnimationFrame(update);
        }

        function drawSeed(seed) {
            const x = seed.x * 50;
            const y = seed.y * 50;
            ctx.fillStyle = 'green';
            ctx.fillRect(x, y, 50, 50);
        }

        // Event listener for key presses
        document.addEventListener('keydown', update);

        // Initial state
        window.game = { state: () => JSON.parse(JSON.stringify({ player, tiles, inventory, day })) };
    </script>
</body>
</html>
